const norm = $('Normalize Order').first().json;
const items = norm.canonical.items || [];
const unmapped = items.filter(i => String(i.plu||'').startsWith('UNMAPPED:') || String(i.plu||'').startsWith('AMBIGUOUS:')).length;
return [{ json: { external_ref: norm.external_ref, status: 'ok', ls_plu_unmapped_count: unmapped }}];

// JET accept failures were swallowed by continueOnFail for months; on 2026-08-07 JET
// tightened its state machine (new -> in_delivery rejected with 403 Wrong status
// transition) and a whole evening of orders sat unaccepted with zero alerts.
// This branch makes any accept failure on a genuinely NEW order visible in dlq_alerts.
const acc = $input.first().json ?? {};
const detail = $('Pin Context').first().json.detail;
const env = $('When called').first().json;
const failed = !!acc.error;
const isNew = detail && detail.status === 'new';
function lit(v) { return v == null || v === '' ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'"; }
let sql = 'SELECT 1';
if (failed && isNew) {
  const msg = String(acc.error.message || 'accept failed').slice(0, 200);
  sql = "INSERT INTO public.dlq_alerts (queue_name, msg_id, external_ref, source, location_key, last_error, attempt_count) VALUES ('takeaway_accept', " + Number(detail.id) + ", " + lit('Takeaway - ' + detail.public_reference) + ", 'takeaway', " + lit(env.location_key) + ", jsonb_build_object('message', " + lit('JET accept failed: ' + msg) + ", 'stage', 'takeaway_accept', 'runbook', 'Accept the order in the JET partner hub NOW, then check the accept API contract'), 1) ON CONFLICT (queue_name, msg_id) DO NOTHING";
}
return [{ json: { sql } }];
